import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    pts = [(0, 0)] * n
    it = iter(data[1:])
    for x, y in zip(it, it):
        pts[x - 1] = (x, y)
    masks = []
    for i, (x, y) in enumerate(pts):
        m = 0
        for j, (a, b) in enumerate(pts):
            if i == j or (x < a and y > b) or (x > a and y < b):
                m |= 1 << j
        masks.append(m)
    seen = { (1 << n) - 1 }
    for m in masks:
        seen.update(s & m for s in tuple(seen))
    print(len(seen) % 998244353)

if __name__ == '__main__':
    main()

