import sys
from collections import defaultdict
MOD=998244353

def factor(x):
    d=2
    out={}
    while d*d<=x:
        while x%d==0:
            out[d]=out.get(d,0)+1
            x//=d
        d+=1
    if x>1:
        out[x]=out.get(x,0)+1
    return out

def solve(n, a):
    fs=[factor(x) for x in a]
    primes=set().union(*(f.keys() for f in fs)) if fs else set()
    ans=1
    for p in primes:
        max_height=sum(f.get(p,0) for f in fs)
        powers=[1]*(max_height+1)
        for i in range(1,max_height+1):
            powers[i]=powers[i-1]*p%MOD
        dp={0:1}
        k=1
        for f in fs:
            e=f.get(p,0)
            nd=defaultdict(int)
            if e==0:
                for gap,val in dp.items():
                    nd[gap]=(nd[gap]+val*powers[gap])%MOD
            else:
                for gap,val in dp.items():
                    for delta in (e,-e):
                        t=gap+delta
                        if t>=0:
                            ng=t
                            mult=powers[t]
                        else:
                            ng=0
                            mult=pow(p,k*(-t),MOD)
                        nd[ng]=(nd[ng]+val*mult)%MOD
            dp=nd
            k+=1
        ans=ans*sum(dp.values())%MOD
    return ans

