def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    vals = data[1:1 + n]
    limit = max(vals)

    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for m in range(p * p, limit + 1, p):
                if spf[m] == m:
                    spf[m] = p

    nim_sum = 0
    for x in vals:
        grundy = 0
        while x > 1:
            grundy += 1
            x //= spf[x]
        nim_sum ^= grundy

    print('Anna' if nim_sum else 'Bruno')

