from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            at[b].append((a, i))

        top1 = top2 = 0
        top_id = -1
        gain = [0] * len(conflictingPairs)
        total = 0

        for r in range(1, n + 1):
            for a, idx in at[r]:
                if a > top1:
                    top2, top1, top_id = top1, a, idx
                elif a == top1:
                    top2 = top1
                    top_id = -1
                elif a > top2:
                    top2 = a

            total += r - top1
            if top_id != -1:
                gain[top_id] += top1 - top2

        return total + max(gain)

