import random, math

def f(k,a,P,b,Q):
 g=math.gcd(a,b)
 if P*b<=Q*a:
  best=((k+a-1)//a)*P
  for y in range(a//g): best=min(best,max(0,(k-b*y+a-1)//a)*P+y*Q)
 else:
  best=((k+b-1)//b)*Q
  for x in range(b//g): best=min(best,x*P+max(0,(k-a*x+b-1)//b)*Q)
 return best
for _ in range(10000):
