 got=f(k,a,P,b,Q)
 want=min(x*P+y*Q for x in range(k//a+2) for y in range(k//b+2) if a*x+b*y>=k)
 if got!=want: print('BAD',k,a,P,b,Q,got,want); break
else: print('all good')

