                ndp[k] = (k * dp[k] + y * dp[k - 1]) % MOD
            dp = ndp
        ans = 0
        falling = 1
        for k in range(1, min(n, x) + 1):
            falling = falling * (x - k + 1) % MOD
            ans = (ans + falling * dp[k]) % MOD
        return ans

