class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # Number of popcount iterations needed to reach 1.
        depth = [0] * (n + 1)
        for x in range(2, n + 1):
            depth[x] = 1 + depth[x.bit_count()]
        allowed = [depth[c] <= k - 1 for c in range(n + 1)]

        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        ans = 0
        prefix = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for c in range(1, n + 1):
                    if allowed[c]:
                        need = c - prefix
                        if 0 <= need <= rem:
                            ans += comb[rem][need]
                prefix += 1
        return ans % MOD

