import sys
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    rows = data[1:]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing_masks = [[0] * 26 for _ in range(n)]

    for i, row in enumerate(rows):
        for j, c in enumerate(row):
            if c != 45:  # '-'
                k = c - 97
                incoming[j][k].append(i)
                outgoing_masks[i][k] |= 1 << j

    dist = [[-1] * n for _ in range(n)]
    # Bit j in remaining[i] is set iff pair (i, j) is undiscovered.
    remaining = [(1 << n) - 1 for _ in range(n)]
    queue = deque()

    # Empty paths and single-edge paths are the centers of palindromes.
    for i in range(n):
        dist[i][i] = 0
        remaining[i] &= ~(1 << i)
        queue.append((i, i))
    for i, row in enumerate(rows):
        for j, c in enumerate(row):
            if c != 45 and dist[i][j] == -1:
                dist[i][j] = 1
                remaining[i] &= ~(1 << j)
                queue.append((i, j))

