import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    k = 2
    for _ in range(m):
        u, v = data[k] - 1, data[k + 1] - 1
        k += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the adjacency matrix over GF(2).
    rank = 0
    pivots = []
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (rows[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        rows[rank], rows[pivot_row] = rows[pivot_row], rows[rank]
        for i in range(n):
            if i != rank and ((rows[i] >> col) & 1):
                rows[i] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free_cols = [c for c in range(n) if c not in pivot_set]
    basis = []
    for free_col in free_cols:
        vec = 1 << free_col
        for i, pivot_col in enumerate(pivots):
            if (rows[i] >> free_col) & 1:
                vec |= 1 << pivot_col
        basis.append(vec)

    # A coordinate must be nonzero in at least one vector in the kernel.
    if any(not any((vec >> v) & 1 for vec in basis) for v in range(n)):
        print("No")
        return

    values = [0] * n
    for bit, vec in enumerate(basis):
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= 1 << bit

    print("Yes")
    print(*values)

if __name__ == "__main__":
    solve()

