import math

N = int(input())

# Let d = x - y. Then N = d * (3*y*y + 3*d*y + d*d),
# and since y >= 1, d^3 < N <= 10^18, so d < 10^6.
for d in range(1, 1_000_001):
    if d * d * d >= N or N % d != 0:
        continue

    q = N // d
    # Solve 3*y^2 + 3*d*y + d^2 = q.
    disc = 12 * q - 3 * d * d
    if disc < 0:
        continue
    root = math.isqrt(disc)
    if root * root != disc:
        continue

    numerator = root - 3 * d
    if numerator > 0 and numerator % 6 == 0:
        y = numerator // 6
        if y > 0:
            print(y + d, y)
            break
else:
    print(-1)

