import sys
from itertools import product

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    X = tuple(x - 1 for x in data[3:3 + M])

    # Exhaustively enumerate strings, maintaining the set of distinct
    # subsequences of lengths up to M. This is an exact (though exponential)
    # fallback for small instances.
    ans = 0
    seq = []
    def dfs(pos, subseqs):
        nonlocal ans
        if pos == N:
            if len(subseqs.get(M, set())) == K ** M - 1 and X not in subseqs.get(M, set()):
                ans += 1
            return
        for c in range(K):
            nxt = {l: set(s) for l, s in subseqs.items()}
            for l in range(min(M, pos + 1), 0, -1):
                if l == 1:
                    nxt.setdefault(1, set()).add((c,))
                else:
                    for t in subseqs.get(l - 1, ()):
                        nxt.setdefault(l, set()).add(t + (c,))
            dfs(pos + 1, nxt)
    dfs(0, {})
    print(ans % MOD)

if __name__ == '__main__':
    main()

