from typing import List
from array import array

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        size = n * m
        # Clockwise order: NE, SE, SW, NW.
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]

        # base[d][k][i]: longest alternating sequence starting at i,
        # traveling in direction d, where k=0 expects 0 and k=1 expects 2.
        base = [[array('H', [0]) * size for _ in range(2)] for _ in range(4)]
        for d, (dr, dc) in enumerate(dirs):
            rows = range(n) if dr == -1 else range(n - 1, -1, -1)
            for r in rows:
                for c in range(m):
                    i = r * m + c
                    rr, cc = r + dr, c + dc
                    for k, value in enumerate((0, 2)):
                        if grid[r][c] == value:
                            length = 1
                            if 0 <= rr < n and 0 <= cc < m:
                                length += base[d][1 - k][rr * m + cc]
                            base[d][k][i] = length

        # With a turn still available, either continue straight or turn
        # clockwise once; the turned suffix is represented by base.
        available = []
        for d, (dr, dc) in enumerate(dirs):
            turn_dr, turn_dc = dirs[(d + 1) % 4]
            cur = [array('H', [0]) * size for _ in range(2)]
            rows = range(n) if dr == -1 else range(n - 1, -1, -1)
            for r in rows:
                for c in range(m):
                    i = r * m + c
                    rr, cc = r + dr, c + dc
                    for k, value in enumerate((0, 2)):
                        if grid[r][c] != value:
                            continue
                        best = 0
                        if 0 <= rr < n and 0 <= cc < m:
                            best = cur[1 - k][rr * m + cc]
                        tr, tc = r + turn_dr, c + turn_dc
                        if 0 <= tr < n and 0 <= tc < m:
                            best = max(best, base[(d + 1) % 4][1 - k][tr * m + tc])
                        cur[k][i] = 1 + best
            available.append(cur)

        answer = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue
                answer = max(answer, 1)
                for d, (dr, dc) in enumerate(dirs):
                    rr, cc = r + dr, c + dc
                    if 0 <= rr < n and 0 <= cc < m:
                        answer = max(answer, 1 + available[d][1][rr * m + cc])
        return answer

