from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        remaining = list(range(1, n + 1))
        ans = []
        last_parity = 0  # 0 means no previous value

        def completions(o, e, m, first_parity):
            if m == 0:
                return 1 if o == 0 and e == 0 else 0
            odd_slots = (m + 1) // 2 if first_parity == 1 else m // 2
            even_slots = m - odd_slots
            if o != odd_slots or e != even_slots:
                return 0
            return math.factorial(o) * math.factorial(e)

        while remaining:
            chosen = None
            for x in remaining:
                p = x & 1
                if last_parity and p == last_parity:
                    continue
                o = odds - (p == 1)
                e = evens - (p == 0)
                next_parity = 2 - p
                # parity values use 1 for odd, 0 even
                next_parity = 1 - p
                cnt = completions(o, e, len(remaining) - 1, next_parity)
                if k > cnt:
                    k -= cnt
                else:
                    chosen = x
                    break
            if chosen is None:
                return []
            ans.append(chosen)
            remaining.remove(chosen)
            if chosen & 1:
                odds -= 1
                last_parity = 1
            else:
                evens -= 1
                last_parity = 0
        return ans

