class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        # Powers of ten modulo k, indexed by decimal position from the right.
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        half = (n + 1) // 2
        weights = []
        for j in range(half):
            mirror = n - 1 - j
            if j == mirror:  # The middle digit occurs only once.
                weights.append(powers[j])
            else:
                weights.append((powers[j] + powers[mirror]) % k)

        # suffix[j] is a bitset of residues achievable by digits j..half-1.
        suffix = [0] * (half + 1)
        suffix[half] = 1  # Only residue 0 is achievable with no digits.
        for j in range(half - 1, -1, -1):
            mask = 0
            for residue in range(k):
                if (suffix[j + 1] >> residue) & 1:
