class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nxt = array('i', [n]) * n
        st = []
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] <= nums[i]:
                st.pop()
            if st:
                nxt[i] = st[-1]
            st.append(i)

        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        log = n.bit_length()
        jumps = [nxt]
        costs = [array('q', (
            nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
            for i in range(n)
        ))]

        for _ in range(1, log):
            prev_j, prev_c = jumps[-1], costs[-1]
            cur_j = array('i', [n]) * n
            cur_c = array('q', [0]) * n
            for i in range(n):
                mid = prev_j[i]
                if mid < n:
                    cur_j[i] = prev_j[mid]
                    cur_c[i] = prev_c[i] + prev_c[mid]
                else:
                    cur_c[i] = prev_c[i]
            jumps.append(cur_j)
            costs.append(cur_c)

        def cost(l, r):
            total = 0
            pos = l
            for p in range(log - 1, -1, -1):
                dest = jumps[p][pos]
                if dest <= r:
                    total += costs[p][pos]
                    pos = dest
            return total + nums[pos] * (r - pos + 1) - (pref[r + 1] - pref[pos])

        answer = 0
        for r in range(n):
            lo, hi = 0, r
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(mid, r) <= k:
                    hi = mid
                else:
                    lo = mid + 1
            answer += r - lo + 1
        return answer

