import sys
from fractions import Fraction

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n,k=data[:2]
    cnt={}
    for i in range(n):
        a,b=data[2+2*i:4+2*i]
        cnt[(a,b)]=cnt.get((a,b),0)+1
    # Outer-to-inner order: descending (A-1)/B.
    types=sorted(cnt, key=lambda z: Fraction(z[0]-1,z[1]), reverse=True)
    dp=[set() for _ in range(k+1)]
    dp[0].add((1,0))
    for a,b in types:
        lim=min(k,cnt[(a,b)])
        # Apply each type as a contiguous block in the sorted ordering.
        old=dp
        nd=[set(s) for s in old]
        for t in range(k+1):
            if not old[t]: continue
            for x,y in old[t]:
                aa,bb=x,y
                for c in range(1,min(lim,k-t)+1):
                    # append this affine function on the inner side
                    aa,bb=aa*a, aa*b+bb
                    nd[t+c].add((aa,bb))
        dp=nd
        # Pareto-prune each cardinality: dominated coefficient pairs cannot help.
        for t in range(1,k+1):
            if len(dp[t])>1:
                arr=sorted(dp[t], reverse=True)
                kept=[]
                best_b=-1
                for aa,bb in arr:
                    if bb>best_b:
                        kept.append((aa,bb)); best_b=bb
                dp[t]=set(kept)
    print(max(a+b for a,b in dp[k]))

if __name__=='__main__': main()

