class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        n = len(s)
        answer = n

        # For a fixed target frequency, process letters from left to right.
        # The state records how many characters are carried into this letter
        # by changes from the previous letter.
        for target in range(1, n + 1):
            dp = {0: 0}
            for i, count in enumerate(counts):
                next_dp = {}
                for incoming, cost in dp.items():
                    available = count + incoming

                    # Finish this letter with frequency zero or target.
                    for wanted in (0, target):
                        if wanted <= available:
                            # Any excess may be changed into the next letter.
                            outgoing = available - wanted
                            op_cost = wanted == 0 and available or available - wanted
                            # Deleting excess is cheaper than carrying it when
                            # it cannot help a later letter.
                            # Keep the option to carry excess forward.
                            value = cost + (available - wanted)
                            old = next_dp.get(outgoing)
                            if old is None or value < old:
                                next_dp[outgoing] = value

                        # Insert characters to reach target.
                        if wanted == target and wanted > available:
                            value = cost + (wanted - available)
                            old = next_dp.get(0)
                            if old is None or value < old:
                                next_dp[0] = value

                    # Delete all available characters.
                    old = next_dp.get(0)
                    if old is None or cost + available < old:
                        next_dp[0] = cost + available

                    # Change excess characters to the next letter.
                    if i < 25:
                        outgoing = available
                        old = next_dp.get(outgoing)
                        if old is None or cost + available < old:
                            next_dp[outgoing] = cost + available

                dp = next_dp
            answer = min(answer, min(dp.values()))

        return answer

