from functools import lru_cache
import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    vals = data[3:]
    v = vals[:n] + vals[n:n + m] + vals[n + m:]

    initial_a = (1 << n) - 1
    initial_b = ((1 << m) - 1) << n
    all_cards = (1 << (n + m + l)) - 1

    @lru_cache(None)
    def win(a, b, turn):
        hand = a if turn == 0 else b
        if hand == 0:
            return False

        table = all_cards ^ (a | b)
        remaining = hand
        while remaining:
            played = remaining & -remaining
            remaining -= played
            played_index = played.bit_length() - 1
            table_after_play = table | played
            next_a = a ^ played if turn == 0 else a
            next_b = b ^ played if turn == 1 else b

            # Play without taking a card.
            if not win(next_a, next_b, 1 - turn):
                return True

            # Alternatively, take any table card smaller than the played card.
            candidates = table_after_play
            while candidates:
                taken = candidates & -candidates
                candidates -= taken
                if v[taken.bit_length() - 1] < v[played_index]:
                    if turn == 0:
                        if not win(next_a | taken, next_b, 1):
                            return True
                    else:
                        if not win(next_a, next_b | taken, 0):
                            return True

        return False

    print('Takahashi' if win(initial_a, initial_b, 0) else 'Aoki')

