import sys

class Fenwick:
    def __init__(self, values):
        self.values = values
        self.n = len(values)
        self.count = [0] * (self.n + 1)
        self.total = [0] * (self.n + 1)
        self.pos = {v: i + 1 for i, v in enumerate(values)}

    def add(self, value, delta):
        i = self.pos[value]
        while i <= self.n:
            self.count[i] += delta
            self.total[i] += value * delta
            i += i & -i

    def prefix_sum(self, bit, i):
        result = 0
        while i:
            result += bit[i]
            i -= i & -i
        return result

    def sum_smallest(self, k):
        if k <= 0:
            return 0
        i = taken = result = 0
        step = 1 << (self.n.bit_length() - 1)
        while step:
            j = i + step
            if j <= self.n and taken + self.count[j] < k:
                i = j
                taken += self.count[j]
                result += self.total[j]
            step >>= 1
        return result + (k - taken) * self.values[i]

    def best_pairing(self, size):
        total = self.prefix_sum(self.total, self.n)
        return total - 2 * self.sum_smallest(size // 2)


