class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(word):
            if not word:
                return list(range(n + 1))

            m = len(word)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = pi[j - 1]
                if word[i] == word[j]:
                    j += 1
                pi[i] = j

            ans = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = pi[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    ans.append(i - m + 1)
                    j = pi[j - 1]
            return ans

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)

        best = n + 1
        for start_b in starts_b:
            # Latest A occurrence that ends no later than B begins.
            ia = bisect_right(starts_a, start_b - len(a)) - 1
            if ia < 0:
                continue

            # Earliest C occurrence that begins after B ends.
            ic = bisect_left(starts_c, start_b + len(b))
            if ic == len(starts_c):
                continue

            best = min(best, starts_c[ic] + len(c) - starts_a[ia])

        return -1 if best == n + 1 else best

