from typing import List

class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = {}
        for v in nums:
            freq[v] = freq.get(v, 0) + 1

        for x in sorted(nums, reverse=True):
            remainder = total - x
            if remainder % 2 == 0:
                sum_value = remainder // 2
                if freq.get(sum_value, 0) - (1 if sum_value == x else 0) > 0:
                    return x
        return 0

