import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        prime = [True] * limit
        prime[0] = prime[1] = False
        for p in range(2, 101):
            if prime[p]:
                for x in range(p * p, limit, p):
                    prime[x] = False

        if prime[n] or prime[m]:
            return -1

        digits = len(str(n))
        places = [10 ** i for i in range(digits)]
        dist = [float('inf')] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            for i, place in enumerate(places):
                digit = (x // place) % 10
                min_digit = 1 if i == digits - 1 else 0

                if digit > min_digit:
                    y = x - place
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (dist[y], y))

                if digit < 9:
                    y = x + place
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (dist[y], y))

        return -1

